def split_row(line: str):
    """Split one CSV line into fields. Fields may be double-quoted; inside a
    quoted field a comma is literal and a doubled quote is a literal quote."""
    fields = []
    current = []
    in_quotes = False
    i = 0
    while i < len(line):
        ch = line[i]
        if ch == '"':
            if in_quotes:
                # Check for doubled quote (literal quote)
                if i + 1 < len(line) and line[i + 1] == '"':
                    current.append('"')
                    i += 1  # skip the second quote
                else:
                    in_quotes = False  # end of quoted field
            else:
                in_quotes = True  # start of quoted field
        elif ch == ',':
            if in_quotes:
                current.append(ch)  # comma inside quotes is literal
            else:
                fields.append(''.join(current))
                current = []
        else:
            current.append(ch)
        i += 1
    fields.append(''.join(current))
    return fields
